#!/bin/sh
# Project entry (generated by agents-init; the file can be renamed): ./<this file> opens the project menu,
# ./<this file> --help lists the commands available without the menu. It calls no model and downloads no code.
#
# It looks for the agenthelm runtime in this order and hands over to the first one found:
#   1. the command named by the AGENTHELM_BIN environment variable
#   2. the user runtime directory ${XDG_DATA_HOME:-~/.local/share}/agenthelm/current
#   3. agenthelm on PATH
#   4. the agent-pack that ships with a plugin in an installed AI client (needs Python 3.11+)
# If none is found it explains why and what to do next, and exits with code 3.
set -u
LAUNCHER_API=1
root=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)

python_ok() {
  "$1" -c 'import sys; sys.exit(0 if sys.version_info >= (3, 11) else 1)' >/dev/null 2>&1
}

find_python() {
  for candidate in "${AGENTHELM_PYTHON:-}" python3 python; do
    [ -n "$candidate" ] || continue
    command -v "$candidate" >/dev/null 2>&1 || continue
    if python_ok "$candidate"; then
      printf '%s\n' "$candidate"
      return 0
    fi
  done
  return 1
}

if [ -n "${AGENTHELM_BIN:-}" ]; then
  if [ -x "$AGENTHELM_BIN" ] || command -v "$AGENTHELM_BIN" >/dev/null 2>&1; then
    exec "$AGENTHELM_BIN" project --project "$root" --via-launcher "$LAUNCHER_API" "$@"
  fi
  echo "The command AGENTHELM_BIN points to does not exist: ${AGENTHELM_BIN}" >&2
  echo "  · Fix or unset this environment variable and try again" >&2
  exit 3
fi

current="${XDG_DATA_HOME:-$HOME/.local/share}/agenthelm/current/bin/agenthelm"
if [ -x "$current" ]; then
  exec "$current" project --project "$root" --via-launcher "$LAUNCHER_API" "$@"
fi

if command -v agenthelm >/dev/null 2>&1; then
  exec agenthelm project --project "$root" --via-launcher "$LAUNCHER_API" "$@"
fi

python=$(find_python) || python=""
if [ -n "$python" ]; then
  # Client plugin caches: <plugin>/<version>/ for Claude Code and Codex, a local directory for Cursor; take the highest version.
  best=$("$python" - "$HOME" "${CLAUDE_CONFIG_DIR:-$HOME/.claude}" "${CODEX_HOME:-$HOME/.codex}" <<'PY'
import re, sys
from pathlib import Path
home, claude, codex = map(Path, sys.argv[1:4])
patterns = [(claude / "plugins/cache/agenthelm/agent-pack", "*/runtime/agenthelm.py"),
            (codex / "plugins/cache/agenthelm/agent-pack", "*/runtime/agenthelm.py"),
            (home / ".cursor/plugins/local/agent-pack", "runtime/agenthelm.py")]
def key(path):
    match = re.search(r"/(\d+)\.(\d+)\.(\d+)/runtime/", path.as_posix())
    return tuple(map(int, match.groups())) if match else (0, 0, 0)
found = [path for base, pattern in patterns for path in base.glob(pattern)]
print(max(found, key=key) if found else "")
PY
)
  if [ -n "$best" ]; then
    exec "$python" "$best" project --project "$root" --via-launcher "$LAUNCHER_API" "$@"
  fi
fi

{
  echo "Cannot open the project menu: this machine has no agenthelm runtime yet."
  if [ -z "$python" ]; then
    old=$(python3 -c 'import platform; print(platform.python_version())' 2>/dev/null || true)
    if [ -n "$old" ]; then
      echo "Reason: the Python found is ${old}; 3.11 or newer is required (everyday agenthelm features need only Python, not an AI client)."
    else
      echo "Reason: no Python 3.11 or newer was found (everyday agenthelm features need only Python, not an AI client)."
    fi
    echo "Next steps:"
    echo "  1. Install Python 3.11+ (on macOS use the python.org installer or Homebrew; on Linux use your distribution's package manager)"
    echo "  2. If it is installed elsewhere: export AGENTHELM_PYTHON=/path/to/python3"
    echo "  3. Then install the runtime (see below)"
  else
    echo "Reason: no agenthelm runtime was found; everyday use needs only Python 3.11+, not an AI client."
  fi
  echo "Install the runtime (once; opening the menu afterwards needs no network):"
  echo "  · Online: npx @sakanano-moe/agenthelm runtime install --apply"
  echo "  · Offline: extract the release archive (agenthelm-v<version>.tar.gz), then run"
  echo "      python3 <extracted-dir>/plugins/agent-pack/runtime/agenthelm.py runtime install --apply"
  echo "  · Runtime already installed: export AGENTHELM_BIN=/path/to/agenthelm"
} >&2
exit 3
